#!/usr/bin/env bash
set -euo pipefail

# JSON is assembled only with hex passwords generated by start.sh.
for password in "$ELASTICSEARCH_READER_PASSWORD" "$ELASTICSEARCH_INGEST_PASSWORD"; do
  if [[ ! $password =~ ^[0-9a-fA-F]{32,128}$ ]]; then
    printf 'Elasticsearch reader and ingest passwords must be 32–128 hexadecimal characters.\n' >&2
    exit 1
  fi
done

request() {
  local path=$1
  curl -fsS --max-time 20 --noproxy '*' -u "elastic:$ELASTIC_PASSWORD" \
    -H 'Content-Type: application/json' -X PUT "http://elasticsearch:9200/$path" --data-binary @- >/dev/null
}

request _security/role/sre_aiobs_reader <<'JSON'
{"indices":[{"names":["nginx-access-*","app-logs-*","vulnerability-findings-*"],"privileges":["read","view_index_metadata"]}]}
JSON
request _security/role/sre_aiobs_ingest <<'JSON'
{"cluster":["monitor"],"indices":[{"names":["nginx-access-*"],"privileges":["create_doc","create_index"]}]}
JSON
request _security/user/sre_aiobs_reader <<JSON
{"password":"$ELASTICSEARCH_READER_PASSWORD","roles":["sre_aiobs_reader"]}
JSON
request _security/user/sre_aiobs_ingest <<JSON
{"password":"$ELASTICSEARCH_INGEST_PASSWORD","roles":["sre_aiobs_ingest"]}
JSON
request _ingest/pipeline/sre_aiobs_nginx_geoip </setup/nginx-geoip-pipeline.json
request _index_template/sre_aiobs_nginx </setup/nginx-index-template.json
request _index_template/sre_aiobs_application </setup/application-index-template.json
request _index_template/sre_aiobs_vulnerability </setup/vulnerability-index-template.json

if [[ -n ${KIBANA_SYSTEM_PASSWORD:-} ]]; then
  if [[ ! $KIBANA_SYSTEM_PASSWORD =~ ^[0-9a-fA-F]{32,128}$ ]]; then
    printf 'Kibana system password must be 32–128 hexadecimal characters.\n' >&2
    exit 1
  fi
  request _security/user/kibana_system/_password <<JSON
{"password":"$KIBANA_SYSTEM_PASSWORD"}
JSON
fi
